/* CAD2D · Cocinas — selección gráfica de Olimpiadas(2) del usuario.
 * 9 dibujos vectoriales reales, evaluados visualmente; se excluyen esquemas simples.
 * Originales no modificados; escala nominal a verificar para proyecto.
 * Inserción en capa 0, color blanco por el motor CAD2D.
 */
(function(){'use strict';
const LIB=window.CAD2D_ARQ_LIBRARY;
if(!LIB||!Array.isArray(LIB.library)||!LIB.Builder)return;
const ids=new Set(LIB.library.map(x=>x.id));let added=0;
const rows=[["ca_co_co09","Cocina de pie · vista frontal","Cocina · equipos",0.8,0.8,""],["ca_co_co06","Cocina con horno · vista frontal","Cocina · equipos",0.8,1.44,""],["ca_co_co33","Anafe seis hornallas · planta","Cocina · equipos",0.8,0.718,""],["ca_co_co44","Anafe cuatro hornallas · planta","Cocina · equipos",0.8,0.8403,""],["ca_co_co30","Anafe industrial · planta","Cocina · equipos",0.8,0.8889,""],["ca_co_lav36","Bacha doble con escurridor · planta","Cocina · equipos",1.4,0.7,""],["ca_co_lav62","Bacha doble · planta","Cocina · equipos",1.4,0.7298,""],["ca_co_lav65","Bacha dos cubetas · planta","Cocina · equipos",1.4,0.8265,""],["ca_co_lav35","Pileta con escurridor · planta","Cocina · equipos",0.8,0.8,""]];
for(const [source,name,cat,w,d,data] of rows){
 const id='olymp2-kitchen-'+source.replace(/[^a-z0-9]+/g,'-');
 if(ids.has(id))continue;
 const bytes=atob(data);if(bytes.length<16||bytes.length%8)continue;
 LIB.library.push({id,source,name,cat,w,d,pro:true,author:'BLOQUES OLIMPIADAS(2).dxf · dibujo original del usuario',
  originalDXF:true,nominalDimensions:true,qualityReview:'Cocinas · selección gráfica',
  wMin:w,wMax:w,dMin:d,dMax:d,
  gen(b,W,D){for(let i=0;i<bytes.length;i+=8){
   const n=j=>bytes.charCodeAt(i+j)+(bytes.charCodeAt(i+j+1)<<8);
   b.line(n(0)/65535*W,n(2)/65535*D,n(4)/65535*W,n(6)/65535*D);
  }}
 });ids.add(id);added++;
}
window.CAD2D_OLYMPIADAS_COCINAS=Object.freeze({count:added,source:'BLOQUES OLIMPIADAS(2).dxf',status:'revisión por paleta'});
})();
